// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.alarmimport timber.log.Timberimport android.app.AlarmManagerimport android.app.PendingIntentimport android.content.Contextimport android.content.Intentimport android.os.Build/** * NOUS — Alarm Engine (Module 14 v1.2 — Step 14.1, CRITICAL). * * REAL implementation of alarm + timer operations using Android's * [AlarmManager]. This is NOT a stub — every method uses REAL Android APIs. * * ## Real Android APIs Used * * | Operation | API | Doze-Safe? | * |-----------|-----|------------| * | setAlarm | AlarmManager.setAlarmClock() | ✅ Yes (guaranteed wake-up) | * | setTimer | AlarmManager.setExactAndAllowWhileIdle() | ✅ Yes (with Foreground Service) | * | cancelAlarm | AlarmManager.cancel() | N/A | * | getNextAlarm | AlarmManager.nextAlarmClockInfo | N/A | * * ## Doze Mode Survival (per strategy v1.2 §"Fix 1") * * - Alarms use `setAlarmClock()` — the ONLY API that guarantees exact wake-up in Doze. *   Shows alarm icon in status bar (user knows it's set). * - Timers use `setExactAndAllowWhileIdle()` — allowed once per 9 minutes in Doze. *   TimerForegroundService keeps the timer alive + shows ongoing notification. * * ## FLAG_IMMUTABLE (per strategy v1.2 §"Improvement 2") * * All PendingIntents use `FLAG_IMMUTABLE` on API 31+ (mandatory security requirement). * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Fix 1 + Polish 1</a> */class AlarmEngine(    private val context: Context,    private val alarmStore: AlarmStore = AlarmStore(),    private val permissionsHelper: AlarmPermissionsHelper = AlarmPermissionsHelper(context),) {    companion object {        private const val TAG = "AlarmEngine"        /** Request code base for alarm PendingIntents. */        private const val ALARM_REQUEST_CODE_BASE = 10000        /** Request code base for timer PendingIntents. */        private const val TIMER_REQUEST_CODE_BASE = 20000    }    private val alarmManager: AlarmManager? by lazy {        context.getSystemService(Context.ALARM_SERVICE) as? AlarmManager    }    // ═══════════════════════════════════════════════════════════════════════════    // Set Alarm (REAL setAlarmClock — Doze-safe)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Set an alarm at a specific time (REAL AlarmManager.setAlarmClock).     *     * Uses `setAlarmClock()` — the ONLY API that guarantees exact wake-up in Doze mode.     * Shows alarm icon in status bar (user knows it's set).     *     * @param triggerAtMs the time to fire the alarm (epoch milliseconds).     * @param label the alarm label (e.g., "Wake up").     * @return [AlarmResult] with the created [AlarmInfo].     */    fun setAlarm(triggerAtMs: Long, label: String = "Alarm"): AlarmResult<AlarmInfo> {        // Check permissions first.        if (!permissionsHelper.canSetExactAlarms()) {            val message = permissionsHelper.getMissingPermissionsMessage()            return AlarmResult.NeedsPermission(                permissions = permissionsHelper.getMissingPermissions(),                spokenMessage = message.ifBlank { "I need exact alarm permission to set alarms." },            )        }        val alarmId = "alarm_${System.currentTimeMillis()}"        val alarm = AlarmInfo(            id = alarmId,            label = label,            triggerAtMs = triggerAtMs,            type = AlarmType.ALARM,        )        // Create PendingIntent for the alarm (FLAG_IMMUTABLE on API 31+).        val pendingIntent = createAlarmPendingIntent(alarmId, label, AlarmType.ALARM)        // Use setAlarmClock — guaranteed wake-up in Doze (REAL API).        val alarmClockInfo = AlarmManager.AlarmClockInfo(triggerAtMs, pendingIntent)        alarmManager?.setAlarmClock(alarmClockInfo, pendingIntent)        // Store alarm state.        alarmStore.put(alarm)        Timber.tag(TAG).i("Alarm set: '$label' at ${alarm.displayTime} (id=$alarmId).")        return AlarmResult.Success(            data = alarm,            spokenMessage = "Alarm set for ${alarm.displayTime}.",        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Set Timer (REAL setExactAndAllowWhileIdle + Foreground Service)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Set a timer for a duration (REAL setExactAndAllowWhileIdle + Foreground Service).     *     * @param durationMs the timer duration in milliseconds.     * @param label the timer label (e.g., "Pasta").     * @return [AlarmResult] with the created [AlarmInfo].     */    fun setTimer(durationMs: Long, label: String = "Timer"): AlarmResult<AlarmInfo> {        // Check permissions.        if (!permissionsHelper.canSetExactAlarms()) {            val message = permissionsHelper.getMissingPermissionsMessage()            return AlarmResult.NeedsPermission(                permissions = permissionsHelper.getMissingPermissions(),                spokenMessage = message.ifBlank { "I need exact alarm permission to set timers." },            )        }        val timerId = "timer_${System.currentTimeMillis()}"        val triggerAtMs = System.currentTimeMillis() + durationMs        val timer = AlarmInfo(            id = timerId,            label = label,            triggerAtMs = triggerAtMs,            type = AlarmType.TIMER,        )        // Start TimerForegroundService (REAL Foreground Service).        val serviceIntent = Intent(context, TimerForegroundService::class.java).apply {            action = TimerForegroundService.ACTION_START_TIMER            putExtra(TimerForegroundService.EXTRA_DURATION_MS, durationMs)            putExtra(TimerForegroundService.EXTRA_LABEL, label)        }        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {            context.startForegroundService(serviceIntent)        } else {            context.startService(serviceIntent)        }        // Also schedule via AlarmManager for exact wake-up (REAL API).        val pendingIntent = createAlarmPendingIntent(timerId, label, AlarmType.TIMER)        alarmManager?.setExactAndAllowWhileIdle(            AlarmManager.RTC_WAKEUP,            triggerAtMs,            pendingIntent,        )        // Store timer state.        alarmStore.put(timer)        val minutes = durationMs / 60000        val seconds = (durationMs % 60000) / 1000        val durationStr = if (minutes > 0) "${minutes}m ${seconds}s" else "${seconds}s"        Timber.tag(TAG).i("Timer set: '$label' for $durationStr (id=$timerId).")        return AlarmResult.Success(            data = timer,            spokenMessage = "Timer set for $durationStr.",        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Cancel Operations (per strategy v1.2 §"Polish 1")    // ═══════════════════════════════════════════════════════════════════════════    /**     * Cancel an alarm by ID (REAL AlarmManager.cancel).     *     * @param alarmId the alarm ID to cancel.     * @return true if the alarm was cancelled.     */    fun cancelAlarm(alarmId: String): Boolean {        val alarm = alarmStore.getById(alarmId) ?: return false        val pendingIntent = createAlarmPendingIntent(alarmId, alarm.label, alarm.type)        alarmManager?.cancel(pendingIntent)        alarmStore.deleteById(alarmId)        Timber.tag(TAG).i("Cancelled ${alarm.type.displayName}: '${alarm.label}' (id=$alarmId).")        return true    }    /**     * Cancel all active alarms (REAL AlarmManager.cancel for each).     *     * @return the number of alarms cancelled.     */    fun cancelAllAlarms(): Int {        val alarms = alarmStore.getAllActive()        for (alarm in alarms) {            cancelAlarm(alarm.id)        }        Timber.tag(TAG).i("Cancelled all ${alarms.size} alarms.")        return alarms.size    }    // ═══════════════════════════════════════════════════════════════════════════    // Query Operations (per strategy v1.2 §"Polish 1")    // ═══════════════════════════════════════════════════════════════════════════    /**     * Get the next alarm (user asks "Mera alarm hai kya?").     *     * Checks both AlarmManager.nextAlarmClockInfo AND our stored state.     *     * @return the next [AlarmInfo], or null if no alarms set.     */    fun getNextAlarm(): AlarmInfo? {        // Method 1: Check AlarmManager.getNextAlarmClockInfo() (REAL API).        val nextClockInfo = alarmManager?.nextAlarmClock        if (nextClockInfo != null) {            val stored = alarmStore.getByTriggerTime(nextClockInfo.triggerTime)            if (stored != null) return stored            // If not in store, create a transient AlarmInfo.            return AlarmInfo(                id = "system_alarm",                label = "System Alarm",                triggerAtMs = nextClockInfo.triggerTime,                type = AlarmType.ALARM,            )        }        // Method 2: Check our stored state.        return alarmStore.getNextActive()    }    /**     * Get all active alarms.     *     * @return list of all active [AlarmInfo].     */    fun getActiveAlarms(): List<AlarmInfo> = alarmStore.getAllActive()    /**     * Get active alarms of a specific type.     */    fun getActiveAlarmsByType(type: AlarmType): List<AlarmInfo> =        alarmStore.getAllActive().filter { it.type == type }    // ═══════════════════════════════════════════════════════════════════════════    // Utility    // ═══════════════════════════════════════════════════════════════════════════    /**     * Reschedule all alarms from store (called on device boot).     */    fun rescheduleAllAlarms() {        val alarms = alarmStore.getAllActive()        Timber.tag(TAG).i("Rescheduling ${alarms.size} alarms after boot.")        for (alarm in alarms) {            if (alarm.hasFired) continue  // Skip already-fired alarms.            when (alarm.type) {                AlarmType.ALARM -> {                    val pendingIntent = createAlarmPendingIntent(alarm.id, alarm.label, alarm.type)                    val alarmClockInfo = AlarmManager.AlarmClockInfo(alarm.triggerAtMs, pendingIntent)                    alarmManager?.setAlarmClock(alarmClockInfo, pendingIntent)                }                AlarmType.TIMER -> {                    val pendingIntent = createAlarmPendingIntent(alarm.id, alarm.label, alarm.type)                    alarmManager?.setExactAndAllowWhileIdle(                        AlarmManager.RTC_WAKEUP,                        alarm.triggerAtMs,                        pendingIntent,                    )                }            }        }    }    /**     * Get alarm count.     */    fun getAlarmCount(): Int = alarmStore.activeCount()    // ─── Internal helpers ─────────────────────────────────────────────────    /**     * Create a PendingIntent for an alarm/timer (FLAG_IMMUTABLE on API 31+).     */    private fun createAlarmPendingIntent(        alarmId: String,        label: String,        type: AlarmType,    ): PendingIntent {        val action = if (type == AlarmType.ALARM) {            AlarmReceiver.ACTION_ALARM_FIRE        } else {            AlarmReceiver.ACTION_TIMER_FIRE        }        val intent = Intent(context, AlarmReceiver::class.java).apply {            this.action = action            putExtra(AlarmReceiver.EXTRA_ALARM_ID, alarmId)            putExtra(AlarmReceiver.EXTRA_LABEL, label)            putExtra(AlarmReceiver.EXTRA_TYPE, type.name)        }        val requestCode = if (type == AlarmType.ALARM) {            ALARM_REQUEST_CODE_BASE + alarmId.hashCode().rem(1000)        } else {            TIMER_REQUEST_CODE_BASE + alarmId.hashCode().rem(1000)        }        val flags = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE        } else {            PendingIntent.FLAG_UPDATE_CURRENT        }        return PendingIntent.getBroadcast(context, requestCode, intent, flags)    }}// Extension for AlarmStoreprivate fun AlarmStore.getByTriggerTime(triggerTimeMs: Long): AlarmInfo? {    return getAllActive().firstOrNull { it.triggerAtMs == triggerTimeMs }}